<template>
  <div class="page-shell event-page">
    <NuxtLink to="/news" class="event-back"><ArrowLeft :size="16" /> 返回游戏资讯</NuxtLink>
    <div class="event-layout"><div class="news-main">
      <header class="event-heading"><p class="eyebrow">{{ newsKinds[event.kind] || '游戏动态' }} / EVENT {{ event.id }}</p><div class="event-flags"><span v-if="isFeatured(event)"><Star :size="13" /> 重点精选</span><span v-if="event.prominence === 'archive'">资讯留档</span><span>{{ newsStatus(event) }}</span></div><h1>{{ event.title }}</h1><p class="event-summary">{{ event.summary }}</p><p v-if="isFeatured(event)" class="event-recommendation"><strong>为什么看</strong>{{ event.recommendation }}</p><div class="event-times"><span>收录于 {{ newsTimestamp(event.created_at) }}</span><span>最近实质更新 {{ newsTimestamp(newsTime(event)) }}</span></div><div class="event-actions"><button @click="copyLink"><Link2 :size="15" /> {{ copyState === 'copied' ? '链接已复制' : '复制事件链接' }}</button><span role="status" aria-live="polite">{{ copyState === 'failed' ? '未能自动复制，请复制下方链接。' : '' }}</span></div><input v-if="copyState === 'failed'" class="event-link" :value="shareUrl" readonly aria-label="事件链接" @focus="($event.target as HTMLInputElement).select()"></header>
      <section v-if="latestUpdate" class="event-latest"><p class="eyebrow">LATEST / 最新进展</p><p>{{ latestUpdate.text }}</p><a :href="latestUpdate.source_url" target="_blank" rel="noopener noreferrer">查看这次进展的来源 <ArrowUpRight :size="14" /></a></section>
      <section class="event-section"><div class="event-section-heading"><h2>事实与依据</h2><span>{{ event.progress.length }} 条</span></div><ol class="event-facts"><li v-for="fact in event.progress" :key="fact.id"><span class="event-evidence-kind">{{ evidenceNames[fact.evidence_kind] || '来源报道' }}</span><p>{{ fact.text }}</p><a :href="fact.source_url" target="_blank" rel="noopener noreferrer">{{ sourceHost(fact.source_url) }} <ArrowUpRight :size="13" /></a></li></ol></section>
      <section v-if="developments.length" class="event-section"><div class="event-section-heading"><h2>事件进展</h2><button :aria-pressed="oldestFirst" @click="oldestFirst = !oldestFirst"><ArrowDownUp :size="14" /> {{ oldestFirst ? '最早在前' : '最新在前' }}</button></div><ol class="event-progress"><li v-for="item in developments" :key="item.id"><div><span>{{ item.action === 'update_event' ? '新增进展' : '首次收录' }}</span><time v-if="item.recorded_at" :datetime="item.recorded_at">{{ newsTimestamp(item.recorded_at) }} 收录</time></div><p>{{ item.text }}</p><a :href="item.source_url" target="_blank" rel="noopener noreferrer">查看来源 <ArrowUpRight :size="13" /></a></li></ol></section>
      <section v-if="event.corrections?.length" class="event-section"><div class="event-section-heading"><h2>更正记录</h2></div><div v-for="(correction, index) in event.corrections" :key="index" class="event-correction"><time :datetime="correction.recorded_at">{{ newsTimestamp(correction.recorded_at) }}</time><p>{{ correction.text }}</p></div></section>
      <section class="event-section"><div class="event-section-heading"><h2>原始报道</h2><span>{{ event.sources.length }} 篇</span></div><div v-for="source in event.sources" :key="source.url" class="event-source"><a :href="source.url" target="_blank" rel="noopener noreferrer"><strong>{{ source.title }}</strong><ArrowUpRight :size="18" /></a><p>{{ sourceHost(source.url) }}<span v-if="source.published_at"> · {{ newsTimestamp(source.published_at) }} 发布</span></p></div><p class="event-source-note">多篇报道可能引用同一出处，报道数量不等于独立证实次数。时间均为 UTC+8。</p></section>
    </div><aside class="event-sidebar"><section><p class="eyebrow">FOLLOW THE SUBJECT</p><h2>继续读这些主题</h2><NuxtLink v-for="topic in event.topics" :key="topic" :to="{ path: '/news', query: { topic } }" class="event-topic">{{ topic }} <ArrowUpRight :size="14" /></NuxtLink></section><section v-if="related.length"><p class="eyebrow">MORE ON THESE SUBJECTS</p><h2>同主题的其他事件</h2><NuxtLink v-for="other in related" :key="other.id" :to="`/news/${other.id}`" class="event-related"><small>{{ newsKinds[other.kind] || '游戏动态' }}</small><h3>{{ other.title }}</h3><span>{{ newsTimestamp(newsTime(other)) }}</span></NuxtLink></section></aside></div>
  </div>
</template>
<script setup lang="ts">
import { ArrowDownUp, ArrowLeft, ArrowUpRight, Link2, Star } from 'lucide-vue-next'
import { evidenceNames, isFeatured, newsKinds, newsStatus, newsTime, newsTimestamp, selectNews } from '~/utils/newsFeed'
const route = useRoute()
const { data } = await useNews()
const found = data.value?.events.find(e => String(e.id) === route.params.id)
if (!found) throw createError({ statusCode: 404, statusMessage: '这条资讯不存在或已撤回' })
const event = found
useSeoMeta({ title: event.title, description: event.summary, ogTitle: event.title, ogDescription: event.summary, ogType: 'article' })
const oldestFirst = ref(false), copyState = ref(''), shareUrl = ref('')
const latestUpdate = computed(() => event.progress.filter(p => p.action === 'update_event').sort((a, b) => (b.recorded_at || '').localeCompare(a.recorded_at || '') || b.id - a.id)[0])
const developments = computed(() => event.progress.filter(p => p.action === 'create_event' || p.action === 'update_event').sort((a, b) => {
  const diff = (a.recorded_at || '').localeCompare(b.recorded_at || '') || a.id - b.id
  return oldestFirst.value ? diff : -diff
}))
const related = computed(() => selectNews(data.value?.events || []).filter(e => e.id !== event.id && e.topics.some(t => event.topics.includes(t))).slice(0, 4))
function sourceHost(url: string) { return new URL(url).hostname.replace(/^www\./, '') }
async function copyLink() {
  shareUrl.value = window.location.href.split('#')[0]!
  try { await navigator.clipboard.writeText(shareUrl.value); copyState.value = 'copied' }
  catch { copyState.value = 'failed' }
}
</script>
<style scoped>
