n{font:11px var(--mono);color:var(--muted)}.event-facts{padding-left:25px}.event-facts li{padding:18px 0 20px 8px;border-bottom:1px solid var(--line)}.event-facts li::marker{font:12px var(--mono);color:var(--blue)}.event-evidence-kind{font-size:11px;color:var(--blue)}.event-facts p,.event-progress p{font-size:15px;line-height:1.9;margin:8px 0 12px}.event-progress{list-style:none;padding:0 0 0 10px;margin:25px 0}.event-progress li{border-left:1px solid var(--line);padding:0 0 25px 22px;position:relative}.event-progress li:before{content:'';position:absolute;width:7px;height:7px;left:-4px;top:6px;border-radius:50%;background:var(--blue)}.event-progress li>div{display:flex;flex-wrap:wrap;gap:8px 14px;font-size:11px;color:var(--blue)}.event-progress time{color:var(--muted);font-size:10px}.event-correction{border-bottom:1px solid var(--line);padding:20px 0}.event-correction time{font-size:11px;color:var(--muted)}.event-correction p{font-size:14px;line-height:1.9}.event-source{padding:20px 0;border-bottom:1px solid var(--line)}.event-source>a{display:flex;justify-content:space-between;gap:15px;font-size:14px;line-height:1.8}.event-source svg{flex-shrink:0;margin-top:4px;color:var(--blue)}.event-source p,.event-source-note{font-size:11px;color:var(--muted);overflow-wrap:anywhere}.event-source-note{line-height:1.8;margin-top:20px}.event-sidebar{padding-top:7px}.event-sidebar section{margin-bottom:38px}.event-sidebar h2{font:700 18px/1.5 var(--serif);margin:12px 0 20px}.event-topic{display:flex;align-items:center;justify-content:space-between;gap:10px;font-size:12px;color:var(--blue);padding:10px 0;border-bottom:1px solid var(--line)}.event-related{display:block;padding:18px 0;border-bottom:1px solid var(--line)}.event-related small{font-size:10px;color:var(--blue)}.event-related h3{font:700 15px/1.8 var(--serif);margin:8px 0}.event-related>span{font-size:10px;color:var(--muted)}a:hover{color:var(--blue)}button:focus-visible,a:focus-visible,input:focus-visible{outline:2px solid var(--blue);outline-offset:4px}@media(max-width:900px){.event-layout{grid-template-columns:1fr;gap:35px}.event-sidebar{border-top:2px solid var(--ink);padding-top:24px}}@media(max-width:500px){.event-summary{font-size:15px}.event-section-heading h2{font-size:20px}}
</style>
